{
  "anomaly_detected": true,
  "confidence": 0.99,
  "anomalies": [
    {
      "category": "other",
      "components": ["FCC1", "NAVC1"],
      "pins": ["FCC1.48", "FCC1.73", "NAVC1.31", "NAVC1.47"],
      "nets": ["UART3_TX_FCC", "UART3_RX_FCC", "I2C3_SDA_NAVC", "UART3_TX_NAVC"],
      "observed": "The STM32H753 VCAP pins 48 and 73 are assigned to UART3_TX_FCC and UART3_RX_FCC. The STM32F405 VCAP_1 pin 31 and VCAP_2 pin 47 are also assigned to signal nets. No VCAP capacitors are shown.",
      "expected": "The MCUs' VCAP pins should have their required capacitors to ground and should not be used as signal connections.",
      "evidence": [
        {
          "source": "schematic",
          "quote": "FCC1: pins 48 and 73 are labeled VCAP and connected to UART3_TX_FCC and UART3_RX_FCC; no VCAP capacitors are shown (FCC sheet, page 2)."
        },
        {
          "source": "schematic",
          "quote": "NAVC1: pins 31 and 47 are labeled VCAP_1 and VCAP_2 and connected to signal nets; no VCAP capacitors are shown (NAVC sheet, page 3)."
        },
        {
          "source": "spec",
          "quote": "Flight Control Computer MCU: STM32H753VITx; Navigation Computer MCU: STM32F405RGTx."
        }
      ],
      "impact": "The VCAP pins provide the MCUs' internal core-regulator supply and require local capacitors. Loading them with signal nets and omitting those capacitors can prevent reliable MCU operation or damage the core supply; the assigned interfaces will also not function as intended.",
      "confidence": 0.99
    }
  ],
  "summary": "Both MCU sheets connect VCAP pins to signal nets and omit the required VCAP capacitors. This is a serious power-connection error that can prevent reliable operation of the flight-control and navigation processors."
}

